      "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<vector xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    xmlns:aapt=\"http://schemas.android.com/aapt\"\n    android:width=\"108dp\"\n    android:height=\"108dp\"\n    android:viewportWidth=\"108\"\n    android:viewportHeight=\"108\">\n\n    <!-- Deep obsidian dark base matching the MANGAL brand logo -->\n    <path\n        android:fillColor=\"#110D0A\"\n        android:pathData=\"M0,0h108v108h-108z\" />\n\n    <!-- Warm radial amber-bronze glow behind the microphone capsule -->\n    <path android:pathData=\"M0,0h108v108h-108z\">\n        <aapt:attr name=\"android:fillColor\">\n            <gradient\n                android:centerX=\"54\"\n                android:centerY=\"48\"\n                android:gradientRadius=\"36\"\n                android:type=\"radial\">\n                <item\n                    android:color=\"#8C521E\"\n                    android:offset=\"0.0\" />\n                <item\n                    android:color=\"#4A290D\"\n                    android:offset=\"0.55\" />\n                <item\n                    android:color=\"#110D0A\"\n                    android:offset=\"1.0\" />\n            </gradient>\n        </aapt:attr>\n    </path>\n</vector>\n"
