      "content": "[versions]\nagp = \"8.7.2\"\nkotlin = \"2.0.21\"\nksp = \"2.0.21-1.0.27\"\ncoreKtx = \"1.15.0\"\nlifecycleRuntimeKtx = \"2.8.7\"\nactivityCompose = \"1.9.3\"\ncomposeBom = \"2024.11.00\"\nnavigationCompose = \"2.8.4\"\nhilt = \"2.52\"\nhiltNavigationCompose = \"1.2.0\"\nroom = \"2.6.1\"\nsqlcipher = \"4.6.1\"\nsqliteKtx = \"2.4.0\"\nsecurityCrypto = \"1.1.0-alpha06\"\ncoroutines = \"1.9.0\"\nserializationJson = \"1.7.3\"\njunit = \"4.13.2\"\n\n[libraries]\nandroidx-core-ktx = { group = \"androidx.core\", name = \"core-ktx\", version.ref = \"coreKtx\" }\nandroidx-lifecycle-runtime-ktx = { group = \"androidx.lifecycle\", name = \"lifecycle-runtime-ktx\", version.ref = \"lifecycleRuntimeKtx\" }\nandroidx-lifecycle-viewmodel-compose = { group = \"androidx.lifecycle\", name = \"lifecycle-viewmodel-compose\", version.ref = \"lifecycleRuntimeKtx\" }\nandroidx-activity-compose = { group = \"androidx.activity\", name = \"activity-compose\", version.ref = \"activityCompose\" }\nandroidx-compose-bom = { group = \"androidx.compose\", name = \"compose-bom\", version.ref = \"composeBom\" }\nandroidx-ui = { group = \"androidx.compose.ui\", name = \"ui\" }\nandroidx-ui-graphics = { group = \"androidx.compose.ui\", name = \"ui-graphics\" }\nandroidx-ui-tooling-preview = { group = \"androidx.compose.ui\", name = \"ui-tooling-preview\" }\nandroidx-material3 = { group = \"androidx.compose.material3\", name = \"material3\" }\nandroidx-navigation-compose = { group = \"androidx.navigation\", name = \"navigation-compose\", version.ref = \"navigationCompose\" }\n\n# Hilt DI\nhilt-android = { group = \"com.google.dagger\", name = \"hilt-android\", version.ref = \"hilt\" }\nhilt-compiler = { group = \"com.google.dagger\", name = \"hilt-android-compiler\", version.ref = \"hilt\" }\nandroidx-hilt-navigation-compose = { group = \"androidx.hilt\", name = \"hilt-navigation-compose\", version.ref = \"hiltNavigationCompose\" }\n\n# Room + SQLCipher Encrypted Storage\nroom-runtime = { group = \"androidx.room\", name = \"room-runtime\", version.ref = \"room\" }\nroom-ktx = { group = \"androidx.room\", name = \"room-ktx\", version.ref = \"room\" }\nroom-compiler = { group = \"androidx.room\", name = \"room-compiler\", version.ref = \"room\" }\nsqlcipher-android = { group = \"net.zetetic\", name = \"sqlcipher-android\", version.ref = \"sqlcipher\" }\nandroidx-sqlite-ktx = { group = \"androidx.sqlite\", name = \"sqlite-ktx\", version.ref = \"sqliteKtx\" }\nandroidx-security-crypto = { group = \"androidx.security\", name = \"security-crypto\", version.ref = \"securityCrypto\" }\n\n# Coroutines & Serialization\nkotlinx-coroutines-core = { group = \"org.jetbrains.kotlinx\", name = \"kotlinx-coroutines-core\", version.ref = \"coroutines\" }\nkotlinx-coroutines-android = { group = \"org.jetbrains.kotlinx\", name = \"kotlinx-coroutines-android\", version.ref = \"coroutines\" }\nkotlinx-serialization-json = { group = \"org.jetbrains.kotlinx\", name = \"kotlinx-serialization-json\", version.ref = \"serializationJson\" }\n\njunit = { group = \"junit\", name = \"junit\", version.ref = \"junit\" }\n\n[plugins]\nandroid-application = { id = \"com.android.application\", version.ref = \"agp\" }\nandroid-library = { id = \"com.android.library\", version.ref = \"agp\" }\nkotlin-android = { id = \"org.jetbrains.kotlin.android\", version.ref = \"kotlin\" }\nkotlin-compose = { id = \"org.jetbrains.kotlin.plugin.compose\", version.ref = \"kotlin\" }\nkotlin-serialization = { id = \"org.jetbrains.kotlin.plugin.serialization\", version.ref = \"kotlin\" }\nhilt-android = { id = \"com.google.dagger.hilt.android\", version.ref = \"hilt\" }\nksp = { id = \"com.google.devtools.ksp\", version.ref = \"ksp\" }\n"
